mapper.select:
SELECT h.*, d.id as dorm_id, d.building as dorm_building, d.room_number as dorm_room_number
FROM health_check h
LEFT JOIN dormitory d ON h.dormitory_id = d.id


        AND h.dormitory_id = #{dormitoryId}


        AND h.check_date = #{checkDate}


        AND h.grade = #{grade}


        AND h.checker_id = #{checkerId}


        AND h.checker_name LIKE CONCAT('%', #{checkerName}, '%')


ORDER BY h.check_date DESC, h.create_time DESC
